(async () => {
  try {
    // Wait 2 seconds for Sannysoft async tests to complete
    await new Promise(r => setTimeout(r, 2000));

    const getTest = (id) => {
      const el = document.getElementById(id);
      if (!el) return { text: 'N/A', passed: false };
      const text = el.textContent?.trim() || '';
      const isFailed = el.classList.contains('failed') || el.classList.contains('result-failed');
      const isPassed = el.classList.contains('passed') || el.classList.contains('result-passed') || (!isFailed && !text.toLowerCase().includes('fail'));
      return { text, passed: isPassed && !isFailed };
    };

    const results = {
      userAgent: getTest('user-agent-result'),
      webdriver: getTest('webdriver-result'),
      advancedWebdriver: getTest('advanced-webdriver-result'),
      chromeRuntime: getTest('chrome-result'),
      permissions: getTest('permissions-result'),
      pluginsLength: getTest('plugins-length-result'),
      languages: getTest('languages-result'),
      webglVendor: getTest('webgl-vendor'),
      webglRenderer: getTest('webgl-renderer'),
      brokenImageDimensions: getTest('broken-image-dimensions')
    };

    const inPageStealth = {
      navigatorWebdriver: navigator.webdriver,
      windowChrome: !!window.chrome,
      pluginsCount: navigator.plugins.length,
      userAgent: navigator.userAgent
    };

    automaNextBlock({
      success: true,
      testName: 'Anti-Bot Fingerprint Benchmark',
      url: window.location.href,
      inPageStealth,
      sannysoftResults: results
    });
  } catch (err) {
    automaNextBlock({ $error: true, message: err.message });
  }
})();
